/* Methods */


/* Reset routines */

void MOD_mkTbGF::reset_RST_N(tUInt8 ARG_rst_in)
{
  PORT_RST_N = ARG_rst_in;
  INST_phase.reset_RST(ARG_rst_in);
  INST_cnt.reset_RST(ARG_rst_in);
}


/* Static handles to reset routines */


/* Functions for the parent module to register its reset fns */


/* Functions to set the elaborated clock id */

void MOD_mkTbGF::set_clk_0(char const *s)
{
  __clk_handle_0 = bk_get_or_define_clock(sim_hdl, s);
}


/* State dumping routine */
void MOD_mkTbGF::dump_state(unsigned int indent)
{
  printf("%*s%s:\n", indent, "", inst_name);
  INST_cnt.dump_state(indent + 2u);
  INST_phase.dump_state(indent + 2u);
}


/* VCD dumping routines */

unsigned int MOD_mkTbGF::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 8u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, bk_clock_vcd_num(sim_hdl, __clk_handle_0), "CLK", 1u);
  vcd_write_def(sim_hdl, num++, "RST_N", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "a__h779", 8u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "cnt_BIT_0___h487", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "cnt_PLUS_1___d97", 16u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x_BIT_7___h1365686", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h810", 16u);
  num = INST_cnt.dump_VCD_defs(num);
  num = INST_phase.dump_VCD_defs(num);
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_mkTbGF::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkTbGF &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
}

void MOD_mkTbGF::vcd_defs(tVCDDumpType dt, MOD_mkTbGF &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 8u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 16u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 16u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.PORT_RST_N) != PORT_RST_N)
      {
	vcd_write_val(sim_hdl, num, PORT_RST_N, 1u);
	backing.PORT_RST_N = PORT_RST_N;
      }
      ++num;
      if ((backing.DEF_a__h779) != DEF_a__h779)
      {
	vcd_write_val(sim_hdl, num, DEF_a__h779, 8u);
	backing.DEF_a__h779 = DEF_a__h779;
      }
      ++num;
      if ((backing.DEF_cnt_BIT_0___h487) != DEF_cnt_BIT_0___h487)
      {
	vcd_write_val(sim_hdl, num, DEF_cnt_BIT_0___h487, 1u);
	backing.DEF_cnt_BIT_0___h487 = DEF_cnt_BIT_0___h487;
      }
      ++num;
      if ((backing.DEF_cnt_PLUS_1___d97) != DEF_cnt_PLUS_1___d97)
      {
	vcd_write_val(sim_hdl, num, DEF_cnt_PLUS_1___d97, 16u);
	backing.DEF_cnt_PLUS_1___d97 = DEF_cnt_PLUS_1___d97;
      }
      ++num;
      if ((backing.DEF_x_BIT_7___h1365686) != DEF_x_BIT_7___h1365686)
      {
	vcd_write_val(sim_hdl, num, DEF_x_BIT_7___h1365686, 1u);
	backing.DEF_x_BIT_7___h1365686 = DEF_x_BIT_7___h1365686;
      }
      ++num;
      if ((backing.DEF_x__h810) != DEF_x__h810)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h810, 16u);
	backing.DEF_x__h810 = DEF_x__h810;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, PORT_RST_N, 1u);
      backing.PORT_RST_N = PORT_RST_N;
      vcd_write_val(sim_hdl, num++, DEF_a__h779, 8u);
      backing.DEF_a__h779 = DEF_a__h779;
      vcd_write_val(sim_hdl, num++, DEF_cnt_BIT_0___h487, 1u);
      backing.DEF_cnt_BIT_0___h487 = DEF_cnt_BIT_0___h487;
      vcd_write_val(sim_hdl, num++, DEF_cnt_PLUS_1___d97, 16u);
      backing.DEF_cnt_PLUS_1___d97 = DEF_cnt_PLUS_1___d97;
      vcd_write_val(sim_hdl, num++, DEF_x_BIT_7___h1365686, 1u);
      backing.DEF_x_BIT_7___h1365686 = DEF_x_BIT_7___h1365686;
      vcd_write_val(sim_hdl, num++, DEF_x__h810, 16u);
      backing.DEF_x__h810 = DEF_x__h810;
    }
}

void MOD_mkTbGF::vcd_prims(tVCDDumpType dt, MOD_mkTbGF &backing)
{
  INST_cnt.dump_VCD(dt, backing.INST_cnt);
  INST_phase.dump_VCD(dt, backing.INST_phase);
}
